-- =============================================================================
-- StaziaMed, CARGA DAS PROVAS CORRIGIDAS, parte 2 (Revalida 2025/2, revalida-2025-2): texto fiel ao caderno oficial do Inep.
-- Gerado por scripts/carga-provas/gerar-correcoes.mjs (ramo carga-provas). Não edite à mão.
-- O que faz: 27 correções de texto em 21 questões (21 campos: enunciado ou alternativa).
--   * Cada campo só é trocado se o texto no banco ainda é EXATAMENTE o de 12/10/2026 (o que a revisão comparou com o PDF).
--     Se alguém mudou esse texto depois, o campo é PULADO e aparece na lista do fim. Nada é apagado.
--   * O texto antigo fica no histórico da questão (Administração > Questões > Editar > Ver histórico de mudanças), com o motivo.
--   * NÃO mexe em gabarito, situação (anulada), explicações, conduta esperada, "o que a questão avalia", tema, figuras.
--   * Regra do sistema (migração 9500): se a questão tinha Análise Stazia publicada, ela sai do ar (explicava o texto antigo);
--     a contagem aparece no fim.
-- Como colar: editor SQL do Supabase, o arquivo INTEIRO, Run. A primeira linha do resultado começa com "OK:" (ou "ATENÇÃO:" se
-- algum campo foi pulado; mostre ao Claude). Pode colar de novo: a segunda vez não muda nada.
-- =============================================================================
create temp table if not exists _carga_texto_resultado (prova text, questao text, codigo text, campo text, situacao text);
delete from _carga_texto_resultado where prova = 'revalida-2025-2';

do $carga_texto$
declare
  v_dados constant jsonb := $carga_dados$[{"id":"revalida_2025_2_q003","code":"REV-2025.2-Q003","campos":{"statement":{"antes_md5":"8b1d99c92471f09b826bf3e5b2d7dba4","depois":"Homem de 45 anos foi encontrado inconsciente por familiares junto a uma escada de sua casa. Familiares o conduziram em carro próprio, sem medidas-padrão de atendimento pré-hospitalar. Não sabem por quanto tempo ficou desacordado e nem sobre o histórico de saúde. Quando deu entrada no pronto-socorro, encontrava-se inconsciente, com equimose e escoriações na região orbital e palpebral direita, além de escoriações na região cervical posterior e em membros à direita. Não apresentava resposta ao comando verbal, mas respirava espontaneamente com frequência normal. Pressão arterial de 140 x 90 mmHg e pupilas isocóricas. Durante a avaliação, abriu os olhos e começou a se mexer, ainda sem responder a questões ou comandos. Após 30 minutos, começou a responder, mas informava não se lembrar de ter caído da escada. Considerando o quadro, a conduta adequada é"}}},{"id":"revalida_2025_2_q010","code":"REV-2025.2-Q010","campos":{"statement":{"antes_md5":"c89a167d183a04e3e312c2dc2599f676","depois":"Paciente feminina de 78 anos, com 24 horas de evolução de dor e abaulamento progressivo em região inguinal direita. Apresentou também alguns episódios de vômitos e diminuição da eliminação de flatos. Antecedentes: neoplasia de mama há 30 anos, diabetes mellitus há 20 anos e tabagista de 40 maços/ano. Ao exame estava normotensa, eucárdica, afebril, eupneica. Índice de massa corporal de 35 kg/m². Abdome globoso, depressível, com abaulamento não redutível e desconforto à palpação em região inguinal direita, com discreta hiperemia local e sem sinais de irritação peritoneal. Resultados dos exames laboratoriais: Exame Resultado Valor de referência Hemoglobina 13 g/dL 11 a 15 g/dL Leucócitos 10.300/mL 4.000 a 11.000/mL Plaquetas 261.000/mm³ 150 a 300.000/mm³ Creatinina 1,8 mg/dL 0,7 a 1,3 mg/dL Ureia 65 mg/dL 40 a 80 mg/dL A hipótese diagnóstica mais provável é","sem_tabela_md5":"e8c72369f575f8d6e67a68b6f0b417a1"}}},{"id":"revalida_2025_2_q012","code":"REV-2025.2-Q012","campos":{"statement":{"antes_md5":"7eddc96563def096293696fb678d06fe","depois":"Homem de 52 anos, branco, solteiro, comparece à consulta agendada na Unidade Básica de Saúde (UBS) desejando realizar revisão clínica e exames laboratoriais. Desde os 35 anos não faz acompanhamento de saúde. Relata história familiar de diabetes e hipertensão, e a mãe faleceu com câncer de pulmão. Sem história familiar de câncer de próstata. Fuma cerca de 2 maços por dia há 21 anos. Exame físico: pressão arterial de 120 x 80 mmHg, índice de massa corporal de 23 kg/m², sem outras alterações. Considerando as recomendações de rastreamento para esse paciente, o médico de família e comunidade deve"}}},{"id":"revalida_2025_2_q015","code":"REV-2025.2-Q015","campos":{"statement":{"antes_md5":"710194c023d1a43141a59b181a27a835","depois":"Homem de 50 anos, queixando-se de astenia e constipação com fezes em fita. Há 15 dias, apresenta edema de membros inferiores até a raiz da região crural, bilateralmente, com pouca melhora à elevação dos membros. Ele perdeu 10 kg em 6 meses. Nega hipertensão arterial e diabetes mellitus e não faz uso de medicamento. Os exames do paciente apresentaram os seguintes resultados: Exame Resultado Valor de referência Pressão arterial 130 x 80 mmHg --- Peso 70 kg --- Hematócrito 35% 48 a 69% Glicemia 88 mg/dL 60 a 100 mg/dL Albumina sérica 1,8 g/dL 3,8 a 4,8 g/dL Creatinina 1,2 mg/dL 0,7 a 1,3 mg/dL Triglicerídeos 200 mg/dL < 150 mg/dL Proteína urinária de 24 horas 3,6 g/24 horas < 100 mg/24 horas Sedimentos proteínas +++ hemácias + (5 por campo) --- Dentre esses achados laboratoriais, quais são necessários para a definição da síndrome renal do paciente?","sem_tabela_md5":"bb3b390cc9a44cf33522aac4a0d0a9de"}}},{"id":"revalida_2025_2_q017","code":"REV-2025.2-Q017","campos":{"statement":{"antes_md5":"aef2881ccca7befc4e21e174e82e344f","depois":"Paciente de 20 anos, sexo masculino, vítima de colisão “automóvel a muro”, sem cinto de segurança, é atendido ainda na cena pelo Serviço Móvel de Atendimento de Urgência (SAMU). Exame físico: paciente torporoso; saturação de O₂ de 60%, em ar ambiente; frequência respiratória de 28 irpm; frequência cardíaca de 112 bpm; pressão arterial de 90 x 50 mmHg. Desvio da traqueia para a direita, turgência de veias jugulares, hipofonese de bulhas cardíacas e diminuição acentuada do murmúrio vesicular à esquerda. Qual é a conduta adequada no atendimento pré-hospitalar?"}}},{"id":"revalida_2025_2_q020","code":"REV-2025.2-Q020","campos":{"statement":{"antes_md5":"953305d18a61ef5a3c0821b4a6e5dda4","depois":"Mulher travesti de 28 anos, profissional do sexo, comparece à Unidade Básica de Saúde (UBS) em demanda espontânea. Relata relações sexuais frequentes com diferentes parceiros, com uso inconsistente de preservativos, principalmente durante relações anais receptivas. Há 2 dias teve uma relação sexual desprotegida com um cliente que se recusou a usar camisinha. Nunca utilizou medicamento para profilaxia pré-exposição (PrEP) ou pós-exposição (PEP) à infecção pelo HIV. Considerando que a paciente está assintomática no momento, qual a melhor estratégia de prevenção?"}}},{"id":"revalida_2025_2_q021","code":"REV-2025.2-Q021","campos":{"statement":{"antes_md5":"21df8b3512ba3b35ac527797954a2cb8","depois":"Mulher de 21 anos comparece à consulta médica em Unidade Básica de Saúde (UBS) para avaliação de amenorreia há 4 meses, sendo descartada gravidez. Paciente relata que há 10 meses iniciou dieta para perder peso, tendo emagrecido nesse período aproximadamente 30 kg. Há 2 dias relata desmaio durante prática de exercício físico e, por isso, realizou eletrocardiograma (ECG) que indicou alterações no segmento ST e na onda T. Paciente nega histórico de diagnóstico de transtorno mental, mora sozinha e sua família é de outra cidade. Afirma manter o padrão alimentar, pois ainda quer perder peso. Ao exame físico, apresenta palidez de mucosa e turgor cutâneo diminuído. Altura = 1,63 m; peso = 39 kg (IMC = 14,7 kg/m²); pressão arterial = 80 x 60 mmHg; frequência cardíaca = 55 bpm e frequência respiratória = 15 irpm. Qual é a conduta adequada nesse momento?"}}},{"id":"revalida_2025_2_q023","code":"REV-2025.2-Q023","campos":{"C":{"antes_md5":"15e6b00b5b8110326d34f506fd5dc74f","depois":"Felipe, 11 anos, acolhido em um abrigo desde os 9 anos, há 3 dias está mais recolhido no seu quarto e dorme quase o tempo todo. Apresenta febre, muita dor no corpo e retro-orbitária, sangramento gengival quando escova os dentes e petéquias pelo corpo."}}},{"id":"revalida_2025_2_q024","code":"REV-2025.2-Q024","campos":{"statement":{"antes_md5":"94a098fc7020e0fdf8a701ccda6fe17d","depois":"Paciente do sexo feminino, 27 anos, é atendida em Unidade de Pronto Atendimento (UPA) com história de dor abdominal, com início em epigástrio há dois dias, contínua, sem fatores de melhora, associada a náuseas e perda de apetite, evoluindo para dor em fossa ilíaca direita há 1 dia e febre de 38,2 °C no dia do atendimento. Nega comorbidades, cirurgias prévias ou uso de medicações regulares. Relata que a última menstruação foi há 23 dias, e apresenta ciclos regulares de 28 dias. Exame físico: regular estado geral, corada, desidratada +/4+, eupneica, anictérica, acianótica; ausculta pulmonar e cardíaca sem alterações; ruídos hidroaéreos diminuídos, descompressão brusca dolorosa em quadrante inferior de abdome à direita. Exame Resultado Valor de referência Hemoglobina 10,7 g/dL 11,5 a 15,5 g/dL Hematócrito 37% 38 a 52% Leucócitos totais 13.400/mm³ 4.000 a 11.000/mm³ Bastonetes 7% 0 a 5% Urina 25 leucócitos/ campo -- Hemácias 8 hemácias/campo -- Beta-hCG sérico negativo -- Considerando o diagnóstico mais provável, a conduta adequada é","sem_tabela_md5":"2c07234975c15bc2d5dac969d4daccfb"}}},{"id":"revalida_2025_2_q038","code":"REV-2025.2-Q038","campos":{"statement":{"antes_md5":"0b06af6ab229e43c97bf05a63e37c724","depois":"Homem de 58 anos deu entrada no pronto-socorro com dor epigástrica irradiada para as costas, iniciada há 2 horas, progressiva, pós-prandial, acompanhada de náuseas, vômitos e sudorese. Relata episódios semelhantes no último ano, que melhoraram com uso de analgésico. Tabagista ativo, alcoolista de 8 doses de destilado por dia há 33 anos, nega comorbidades. Exame físico: corado, acianótico, anictérico, sudoreico, fácies de dor, agitado. Índice de massa corporal de 23 kg/m²; pressão arterial de 150 x 90 mmHg; frequência cardíaca de 74 bpm; frequência respiratória de 18 irpm; temperatura axilar de 37 ºC. Abdome globoso, distendido, timpânico, peristalse presente, doloroso à palpação do epigástrio e hipocôndrio esquerdo. Os exames laboratoriais apresentam os seguintes resultados: Exame Resultado Valor de referência Hematócrito 46% 36 a 46% Hemoglobina 15,0 g/dL 12,0 a 15,0 g/dL Leucócitos 12.000/mm³ 4.000 a 10.000/mm³ Glicose 120 mg/dL 70 a 99 mg/dL Bilirrubina total 1,2 mg/dL 0,3 a 1,3 mg/dL Ureia 38 mg/dL 15 a 40 mg/dL Cálcio 8,9 mg/dL 8,7 a 10,2 mg/dL Amilase 35 U/L 20 a 96 U/L Lipase 12 U/L 3 a 43 U/L Fosfatase alcalina 81 U/L 33 a 96 U/L LDH 127 U/L 100 a 190 U/L TGO 36 U/L 5 a 40 U/L Qual é o provável diagnóstico?","sem_tabela_md5":"54a77cb42c0c23b87ac0fdec9523d4b5"}}},{"id":"revalida_2025_2_q039","code":"REV-2025.2-Q039","campos":{"B":{"antes_md5":"397d325823b2059188c9b13aa69b8cfa","depois":"solicitar dopplervelocimetria obstétrica para avaliar o bem-estar fetal e planejar o manejo com base no resultado."}}},{"id":"revalida_2025_2_q042","code":"REV-2025.2-Q042","campos":{"statement":{"antes_md5":"8647f35057c652e28aa9d3cdeb218ba8","depois":"Recém-nascido de 14 dias, hipoativo e com desconforto respiratório, é levado para avaliação na Unidade de Pronto Atendimento (UPA). Antecedentes obstétricos: não foi realizado pré-natal e o parto ocorreu a termo no domicílio. Exame clínico: hipoativo e pouco responsivo, hipocorado, cianótico. Aparelho respiratório: 70 irpm com tiragem subcostal. Murmúrio vesicular diminuído bilateralmente. Saturação de O₂ em ar ambiente de 82%. Aparelho cardiovascular: pulsos débeis, tempo de perfusão capilar de 5 segundos. Frequência cardíaca de 160 bpm, com ritmo cardíaco regular. Abdome globoso, com fígado a 2,5 cm do rebordo costal direito, presença de halo de hiperemia e edema em torno do coto umbilical. O diagnóstico e as condutas adequadas são, respectivamente,"}}},{"id":"revalida_2025_2_q043","code":"REV-2025.2-Q043","campos":{"statement":{"antes_md5":"2d396928d0c2f8cd1465faa2c3207de7","depois":"Homem de 66 anos, em pós-operatório precoce de revascularização cardíaca, é encaminhado ao pronto-socorro, com queixa de dor abdominal progressiva em quadrante inferior esquerdo há 5 dias e piora há 1 dia, com aumento do número de evacuações para 3 vezes ao dia. Relata febre não aferida. Exame físico: bom estado geral, eupneico, pressão arterial de 110 x 60 mmHg, temperatura axilar de 38 °C e frequência cardíaca de 100 bpm. Ao exame abdominal, defesa voluntária da musculatura e dor à palpação superficial e profunda, com massa em quadrante inferior esquerdo. Ao toque retal, presença de uma massa flutuante dolorosa à esquerda. Tomografia de abdome com contraste: densificação dos planos gordurosos adjacente ao sigmoide, associada a coleção de 100 mm³ no local. Após iniciada a antibioticoterapia sistêmica, qual é a conduta mais adequada para esse paciente?"}}},{"id":"revalida_2025_2_q046","code":"REV-2025.2-Q046","campos":{"statement":{"antes_md5":"eb0dc8080ff4b89ea2b1b74eec5b938d","depois":"Homem de 32 anos apresenta quadro de dor lombar crônica de início insidioso, com duração aproximada de 6 meses, que piora pela manhã e melhora com o movimento. Refere rigidez matinal, principalmente nas regiões lombar e sacroilíaca, com duração de mais de 30 minutos, com dor nas articulações sacroilíacas e sensação de fadiga durante as últimas semanas. Não há histórico de trauma. A história familiar é positiva para doenças reumatológicas, mas o paciente desconhece diagnósticos específicos. O painel de autoanticorpos apresenta: Anticorpo antinuclear (ANA) Positivo Título 1:80 Padrão homogêneo/difuso Anticorpo anti-DNA dupla hélice Negativo Antígeno leucocitário humano B27 (HLA-B27) Positivo Fator reumatoide Negativo Anticorpo anti-CCP Negativo Anticorpo anti-Ro Negativo Anticorpo anti-La Negativo Com base no caso clínico e nos exames laboratoriais apresentados, qual é o diagnóstico mais provável?","sem_tabela_md5":"5649074581b3f2f32c54921305b2684c"}}},{"id":"revalida_2025_2_q058","code":"REV-2025.2-Q058","campos":{"statement":{"antes_md5":"41aa717311b1c61523ca7af7dabc1336","depois":"Mulher de 30 anos, sem doenças prévias, dá entrada em Unidade de Pronto Atendimento (UPA). Relata que há 2 horas, após ingestão de bebida alcoólica e energéticos, teve palpitações. Ao exame, está consciente, orientada e com hálito etílico. Apresenta-se com pressão arterial de 100 x 70 mmHg e frequência cardíaca de 150 bpm, frequência respiratória de 14 irpm e saturação de O₂ de 94% ao ar ambiente. À ausculta cardíaca, apresenta-se taquicárdica, com ritmo irregular. Exames dos aparelhos respiratório e neurológico inalterados. Na unidade de emergência, foi realizado o eletrocardiograma que apresenta o ritmo na derivação D2. Quais são, respectivamente, o diagnóstico e o tratamento de primeira escolha para essa paciente?"}}},{"id":"revalida_2025_2_q060","code":"REV-2025.2-Q060","campos":{"statement":{"antes_md5":"2778ba2c86f2e5446e888bbe28dba521","depois":"Homem de 35 anos, vítima de agressão física por arma branca, é encontrado caído no chão de um bar. Apresenta agitação psicomotora, cianose, turgência jugular e desvio da traqueia à esquerda. Pressão arterial de 90 x 40 mmHg; frequência cardíaca de 120 bpm; saturação periférica de O₂ de 87%. No local, o socorrista nota uma faca com lâmina penetrada no quarto espaço intercostal direito, na linha axilar anterior. O murmúrio vesicular encontra-se diminuído em todo o hemitórax direito, que se encontra hipertimpânico. A conduta imediata no atendimento pré-hospitalar deve ser"}}},{"id":"revalida_2025_2_q062","code":"REV-2025.2-Q062","campos":{"statement":{"antes_md5":"c4a9f3823d06eece1ee4b8f5c4301b8c","depois":"Homem negro de 22 anos, cisgênero, comparece à Unidade Básica de Saúde (UBS). Relata dificuldades para dormir desde o dia em que começou a namorar seu atual companheiro, há 4 meses. Fala sobre o aumento do número de óbitos por homofobia na cidade. Queixa-se de dor de cabeça frequente, geralmente do lado direito, de intensidade entre 5/10 e 7/10, que dura algumas horas, às vezes até o outro dia, e melhora após o sono. Os episódios ocorrem 2 vezes por mês, associados à vontade de vomitar e incômodo com barulho. Não há melhora com uso de ibuprofeno, nem paracetamol. Diz que não se alimenta bem, come muita fritura e bebe 3 xícaras de café por dia, além de não praticar atividade física. Exame físico: índice de massa corporal de 35 kg/m². Qual é a conduta adequada para o caso?"}}},{"id":"revalida_2025_2_q065","code":"REV-2025.2-Q065","campos":{"statement":{"antes_md5":"740f8688eb0cbc20d69a3f29a7495a9e","depois":"Mulher de 32 anos, previamente hígida, apresenta quadro de disúria, polaciúria, urgência miccional e dor lombar esquerda há 3 dias, sem outras queixas genito-urinárias. Vem tomando analgésicos e anti-inflamatórios não esteroides, porém sem melhora. No 4º dia, evoluiu com febre, calafrios, náuseas e vômitos, piora da lombalgia esquerda e astenia intensa. Foi levada ao pronto-socorro pelo seu esposo. Ao exame, temperatura axilar de 38,3 °C; frequência cardíaca de 110 bpm; frequência respiratória de 32 irpm; pressão arterial de 70 x 40 mmHg; saturação de O₂ de 96% em ar ambiente. Consciente e orientada, corada, desidratada (+/4+), acianótica, anictérica. Ausculta cardíaca e pulmonar sem alterações. Abdome doloroso em flanco esquerdo e hipogástrio. Sinal de Giordano positivo à esquerda. Extremidades sem alterações. Realizou exame de imagem que descartou a presença de cálculos urinários. Com base no diagnóstico mais provável, qual é a conduta adequada?"}}},{"id":"revalida_2025_2_q076","code":"REV-2025.2-Q076","campos":{"statement":{"antes_md5":"2cd80f48a14f8055f3e23d8e8892a383","depois":"Paciente do sexo masculino, 71 anos, aposentado, ex-trabalhador rural durante 35 anos, procura atendimento médico na Unidade Básica de Saúde (UBS) com dor lombar, predominante no período noturno, associada à perda de peso há cerca de 15 dias. Apresenta dores em região cervical, ombros e joelhos, exacerbadas aos esforços físicos. Relata transplante hepático há 2 anos, por câncer de fígado, fazendo uso regular de medicamento imunossupressor. Exame físico: bom estado geral, eupneico, acianótico, anictérico, afebril e normocorado. Ausculta cardíaca e respiratória sem alterações. Abdome normotenso, indolor à palpação, sem visceromegalias. Extremidades aquecidas e perfundidas, sem edema. Dorso: acentuada lordose lombar e dor à mobilização da coluna lombossacra. Avaliação neuromuscular: força muscular preservada, sensibilidade sem alterações e reflexos normais. Diante desse caso, qual é o exame e a conduta adequada, respectivamente?"}}},{"id":"revalida_2025_2_q097","code":"REV-2025.2-Q097","campos":{"statement":{"antes_md5":"38886ee2f49f0cd8ab1365f61d6ec070","depois":"Menino de 10 anos, com anemia falciforme, foi trazido à Unidade de Pronto Atendimento (UPA) com quadro de febre alta há 48 horas e sintomas gripais. Durante a observação na unidade, evoluiu com dor torácica e queda na saturação de O₂ de 89% em ar ambiente. Ausculta pulmonar: diminuição discreta do murmúrio vesicular à esquerda. Frequência cardíaca normal. A hipótese diagnóstica e a conduta inicial são, respectivamente,"}}},{"id":"revalida_2025_2_q099","code":"REV-2025.2-Q099","campos":{"statement":{"antes_md5":"ab1eddae2ae06862162b1dbe1a97e998","depois":"Mãe leva a filha de 13 anos e 15 dias à consulta em Unidade Básica de Saúde (UBS). A filha demonstra preocupação, pois ainda não menstruou, fato que já ocorreu com todas as suas amigas. No histórico, consta telarca aos 10 anos. Relata que há uma semana começou com secreção vaginal transparente e sem odor, que por vezes molhava a roupa íntima. Informa não ter tido relações sexuais até o momento da consulta. Exame físico: índice de massa corporal de 18,5 kg/m²; estatura de 1,58 m; pressão arterial de 115 x 80 mmHg; mamas M3 e pelos pubianos P3 (escala de Tanner). Presença de hímen íntegro com orifício anular. Ausência de nódulos inguinais. De acordo com a história clínica, qual é a conduta adequada?"}}}]$carga_dados$::jsonb;
  r jsonb;
  c record;
  q public.questions;
  v_statement text;
  v_options jsonb;
  v_atual text;
  v_situacao text;
  v_muda boolean;
  v_analises integer := 0;
begin
  perform set_config('sqie.reason', 'Texto fiel ao caderno oficial do Inep (carga das provas corrigidas, revisão de 12/10/2026)', true);
  for r in select value from jsonb_array_elements(v_dados) loop
    select * into q from public.questions x where x.id = r ->> 'id' for update;
    if not found then
      insert into _carga_texto_resultado values ('revalida-2025-2', r ->> 'id', r ->> 'code', '-', 'pulado: questão não encontrada no banco');
      continue;
    end if;
    v_statement := q.statement;
    v_options := q.options;
    v_muda := false;
    for c in select key as campo, value as v from jsonb_each(r -> 'campos') loop
      v_atual := case when c.campo = 'statement' then q.statement
                      else (select o ->> 'text' from jsonb_array_elements(q.options) o where o ->> 'id' = c.campo limit 1) end;
      if v_atual is not distinct from (c.v ->> 'depois') or md5(v_atual) is not distinct from (c.v ->> 'sem_tabela_md5') then
        v_situacao := 'já estava corrigido';
      elsif v_atual is not null and md5(v_atual) = c.v ->> 'antes_md5' then
        v_situacao := 'corrigido agora';
        v_muda := true;
        if c.campo = 'statement' then
          v_statement := c.v ->> 'depois';
        else
          v_options := (select jsonb_agg(case when o ->> 'id' = c.campo then jsonb_set(o, '{text}', to_jsonb(c.v ->> 'depois')) else o end order by n)
                        from jsonb_array_elements(v_options) with ordinality as x (o, n));
        end if;
      else
        v_situacao := 'pulado: o texto no banco mudou depois de 12/10/2026';
      end if;
      insert into _carga_texto_resultado values ('revalida-2025-2', q.id, q.code, case c.campo when 'statement' then 'enunciado' else 'alternativa ' || c.campo end, v_situacao);
    end loop;
    if v_muda then
      v_analises := v_analises + (select count(*)::int from public.question_analysis a where a.question_id = q.id and a.is_current and a.status = 'published');
      update public.questions set statement = v_statement, options = v_options where id = q.id;
      perform public.admin_log('question.updated', q.id, jsonb_build_object('status', q.status, 'reason', 'Texto fiel ao caderno oficial do Inep (carga das provas corrigidas, revisão de 12/10/2026)'));
    end if;
  end loop;
  insert into _carga_texto_resultado values ('revalida-2025-2', '-', '-', 'análises', 'análises publicadas que saíram do ar: ' || v_analises);
  perform set_config('sqie.reason', '', true);
end
$carga_texto$;

select resultado, detalhe from (
  select 0 as ordem,
         case when count(*) filter (where situacao like 'pulado%') = 0 then 'OK: ' else 'ATENÇÃO: ' end
           || 'Revalida 2025/2: '
           || count(distinct questao) filter (where situacao = 'corrigido agora') || ' questões corrigidas agora ('
           || count(*) filter (where situacao = 'corrigido agora') || ' campos); '
           || count(*) filter (where situacao = 'já estava corrigido') || ' campos já estavam corrigidos; '
           || count(*) filter (where situacao like 'pulado%') || ' pulados (de 21)' as resultado,
         max(situacao) filter (where campo = 'análises') as detalhe
  from _carga_texto_resultado where prova = 'revalida-2025-2'
  union all
  select 1, 'PULADO: ' || codigo || ' (' || campo || ')', situacao
  from _carga_texto_resultado where prova = 'revalida-2025-2' and situacao like 'pulado%'
) x order by ordem, resultado;
